<template><section class="card"><h1>소비 로그 작성</h1><form class="form" @submit.prevent="submit"><div class="field"><label>카테고리</label><select v-model="form.category" required><option disabled value="">선택</option><option v-for="c in categories" :key="c.id" :value="c.id">{{c.name}}</option></select></div><div class="field"><label>금액</label><input v-model.number="form.amount" type="number" min="1" required></div><div class="field"><label>내용</label><textarea v-model="form.content"></textarea></div><div class="field"><label>파일</label><input type="file" @change="e=>file=e.target.files[0]"></div><button>기록하기</button></form><p v-if="error" class="error">{{error}}</p></section></template>
<script setup>import { onMounted, reactive, ref } from 'vue'; import { useRouter } from 'vue-router'; import api from '@/api/axios'; const router=useRouter(); const categories=ref([]); const file=ref(null); const error=ref(''); const form=reactive({category:'',amount:'',content:''}); const load=async()=>{await api.post('/api/v1/expenses/categories/seed/'); categories.value=(await api.get('/api/v1/expenses/categories/')).data}; const submit=async()=>{const fd=new FormData(); fd.append('category',form.category); fd.append('amount',form.amount); fd.append('content',form.content); if(file.value) fd.append('media',file.value); try{await api.post('/api/v1/expenses/logs/',fd,{headers:{'Content-Type':'multipart/form-data'}}); router.push({name:'MyLogsView'})}catch(e){error.value=JSON.stringify(e.response?.data||e.message,null,2)}}; onMounted(load)</script>
